program.compute:
pool = read('/input/options')
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        result = selection
    else:
        result = None
else:
    write('/output/selection', result)
    selection = result
if result is not None:
    delivery = receipt('report')
    if delivery == 'unattempted':
        send('report', 'team', result)
    elif delivery == 'unknown':
        state = status('report')
        if state == 'not_sent':
            send('report', 'team', result)
        elif state == 'sent':
            delivery = 'success'
    if exists('/tmp/cache'):
        delete('/tmp/cache')

